From 8f526fd02a5308bc3f92bab94fc661004d843c6b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:25:40 +0100
Subject: [PATCH] foldermodel: add Open Terminal Here to the folder item menu

Right-clicking a folder on the desktop or in Folder View offered no way
to open a terminal in it, unlike Dolphin. Add an Open Terminal Here
action for local folders that opens a terminal in each selected folder.

BUG: 459033
---
 .../desktop/plugins/folder/foldermodel.cpp    | 33 ++++++++++++++++++-
 .../desktop/plugins/folder/foldermodel.h      |  1 +
 2 files changed, 33 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..1b28965126 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -79,6 +79,7 @@
 #include <KShell>
 #include <KStandardShortcut>
 #include <KStringHandler>
+#include <KTerminalLauncherJob>
 #include <KUrlMimeData>

 #include <Plasma/Applet>
@@ -921,6 +922,23 @@ void FolderModel::showTarget()
     });
 }

+void FolderModel::openTerminalHere()
+{
+    if (!KAuthorized::authorizeAction(QStringLiteral("shell_access"))) {
+        return;
+    }
+
+    const QModelIndexList indexes = m_selectionModel->selectedIndexes();
+    for (const QModelIndex &index : indexes) {
+        const KFileItem item = itemForIndex(index);
+        if (!item.isNull() && item.isDir() && !item.localPath().isEmpty()) {
+            auto job = new KTerminalLauncherJob(QString());
+            job->setWorkingDirectory(item.localPath());
+            job->start();
+        }
+    }
+}
+
 void FolderModel::rename(int row, const QString &name)
 {
     if (row < 0) {
@@ -1863,8 +1881,12 @@ void FolderModel::createActions()
     showTarget->setEnabled(false);
     connect(showTarget, &QAction::triggered, this, &FolderModel::showTarget);

+    QAction *openTerminalHere = new QAction(QIcon::fromTheme(QStringLiteral("utilities-terminal")), i18nc("@action:inmenu", "Open Terminal Here"), this);
+    connect(openTerminalHere, &QAction::triggered, this, &FolderModel::openTerminalHere);
+
     m_actionCollection.addAction(QStringLiteral("open"), actOpen);
     m_actionCollection.addAction(QStringLiteral("showTarget"), showTarget);
+    m_actionCollection.addAction(QStringLiteral("openTerminalHere"), openTerminalHere);
     m_actionCollection.addAction(QStringLiteral("cut"), cut);
     m_actionCollection.addAction(QStringLiteral("undo"), undo);
     m_actionCollection.addAction(QStringLiteral("copy"), copy);
@@ -1949,6 +1971,11 @@ void FolderModel::updateActions()
         showTarget->setEnabled(items.count() == 1 && items.at(0).isLink());
     }

+    if (QAction *openTerminalHere = m_actionCollection.action(QStringLiteral("openTerminalHere"))) {
+        openTerminalHere->setVisible(!indexes.isEmpty() && itemProperties.isLocal() && itemProperties.isDirectory()
+                                     && KAuthorized::authorizeAction(QStringLiteral("shell_access")));
+    }
+
     if (m_newMenu) {
         m_newMenu->checkUpToDate();
         m_newMenu->setWorkingDirectory(m_dirModel->dirLister()->url());
@@ -2138,7 +2165,11 @@ void FolderModel::openContextMenu(QQuickItem *visualParent, Qt::KeyboardModifier
         menu->addSeparator();

         if (!isTrash && !isTrashLink) {
-            m_fileItemActions->addActionsTo(menu);
+            QList<QAction *> additionalActions;
+            if (QAction *openTerminalHere = m_actionCollection.action(QStringLiteral("openTerminalHere")); openTerminalHere->isVisible()) {
+                additionalActions << openTerminalHere;
+            }
+            m_fileItemActions->addActionsTo(menu, KFileItemActions::MenuActionSource::All, additionalActions);

             // Copy To, Move To
             KSharedConfig::Ptr dolphin = KSharedConfig::openConfig(QStringLiteral("dolphinrc"));
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..acfad83c90 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -229,6 +229,7 @@ public:
     Q_INVOKABLE void run(int row);
     Q_INVOKABLE void runSelected();
     Q_INVOKABLE void showTarget();
+    Q_INVOKABLE void openTerminalHere();

     Q_INVOKABLE void rename(int row, const QString &name);
     Q_INVOKABLE int fileExtensionBoundary(int row);
-- 
